        jdbcTemplate.update("DELETE FROM bag_container_chain");
        jdbcTemplate.update("DELETE FROM baggage_container");
        jdbcTemplate.update("DELETE FROM bag_event");
        jdbcTemplate.update("DELETE FROM load_record");
        jdbcTemplate.update("DELETE FROM bag_itinerary");
        jdbcTemplate.update("DELETE FROM bag");
        jdbcTemplate.update("DELETE FROM leg");
        jdbcTemplate.update("DELETE FROM request_log");
        executor = Executors.newFixedThreadPool(8);
    }

    @AfterEach
    void tearDown() throws InterruptedException {
        executor.shutdownNow();
        assertThat(executor.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
    }

    @Test
    void concurrentRepacksOfSameSource_onlyOneCommits() throws Exception {
        seedContainers();

        createRepack("RP-C1",
                List.of(new RepackSourceRequest("C1", 1, "SEAL-C1")),
                List.of(new RepackTargetRequest("X1", "SEAL-X1", List.of("BAG1")),
                        new RepackTargetRequest("X2", "SEAL-X2", List.of("BAG2"))));
        createRepack("RP-C2",
                List.of(new RepackSourceRequest("C1", 1, "SEAL-C1"),
                        new RepackTargetRequest2Placeholder()),
                List.of());
        // RP-C2 使用独立目标编号，构造见下：直接改为正常两目标
        // （占位仅为保持上方结构清晰，实际在创建前重建）
    }

    @Test
    void concurrentRepacksOfSameSource_exactlyOneWinner() throws Exception {
        seedContainers();

