        Integer sealed = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM baggage_container WHERE status = 'SEALED'", Integer.class);
        // C2 始终 SEALED，胜方两个目标 SEALED
        assertThat(sealed).isEqualTo(3);
